#ifndef WS_CFG_VARCONVERTER_HPP
#define WS_CFG_VARCONVERTER_HPP

#include <string>
#include <sstream>
#include <stdexcept>
#include <list>
#include <vector>
#include <set>
#include <unordered_set>
#include <map>
#include <yaml-cpp/yaml.h>

namespace ws {
namespace cfg {

template <typename From, typename To> class VarConverter {
public:
  constexpr operator()(const From& val) const noexcept -> To {
    return static_cast<To>(val);
  }
};

// Specializations

template <>
VarConverter<From, std::string>::operator()(const From& val) const noexcept -> std::string {
  return std::to_string(val);
}

template <typename To>
VarConverter<std::string, To>::operator()(const std::string& val) const noexcept -> To {
  try {
    To result;
    std::istringstream ss(val);
    ss >> result;
    if (ss.fail()) {
      throw std::invalid_argument("Failed to parse string to " + typeid(To).name());
    }
    return result;
  } catch (const std::exception& e) {
    throw std::invalid_argument("Failed to parse string to " + typeid(To).name() + ": " + std::string(e.what()));
  }
}

template <typename T>
VarConverter<std::string, std::list<T>>::operator()(const std::string& val) const noexcept {
    throw std::invalid_argument("Not implemented for list conversion from string.");
}

template <typename T>
VarConverter<std::list<T>, std::string>::operator()(const std::list<T>& val) const noexcept -> std::string {
  YAML::Node node;
  for (const auto& item : val) {
    node.push_back(item);
  }
  return node.dump();
}

template <typename T>
VarConverter<std::string, std::vector<T>>::operator()(const std::string& val) const noexcept {
    throw std::invalid_argument("Not implemented for vector conversion from string.");
}

template <typename T>
VarConverter<std::vector<T>, std::string>::operator()(const std::vector<T>& val) const noexcept -> std::string {
  YAML::Node node;
  for (const auto& item : val) {
    node.push_back(item);
  }
  return node.dump();
}

template <typename T>
VarConverter<std::string, std::set<T>>::operator()(const std::string& val) const noexcept {
    throw std::invalid_argument("Not implemented for set conversion from string.");
}

template <typename T>
VarConverter<std::set<T>, std::string>::operator()(const std::set<T>& val) const noexcept -> std::string {
  YAML::Node node;
  for (const auto& item : val) {
    node.push_back(item);
  }
  return node.dump();
}

template <typename T>
VarConverter<std::string, std::unordered_set<T>>::operator()(const std::string& val) const noexcept {
    throw std::invalid_argument("Not implemented for unordered_set conversion from string.");
}

template <typename T>
VarConverter<std::unordered_set<T>, std::string>::operator()(const std::unordered_set<T>& val) const noexcept -> std::string {
  YAML::Node node;
  for (const auto& item : val) {
    node.push_back(item);
  }
  return node.dump();
}

template <typename T>
VarConverter<std::string, std::map<std::string, T>>::operator()(const std::string& val) const noexcept {
    throw std::invalid_argument("Not implemented for map conversion from string.");
}

template <typename T>
VarConverter<std::map<std::string, T>, std::string>::operator()(const std::map<std::string, T>& val) const noexcept -> std::string {
  YAML::Node node;
  for (const auto& [key, value] : val) {
    node[key] = value;
  }
  return node.dump();
}

} // namespace cfg
} // namespace ws

#endif // WS_CFG_VARCONVERTER_HPP

#ifndef WS_CFG_CONFIG_HPP
#define WS_CFG_CONFIG_HPP

#include <string>
#include <sstream>
#include <stdexcept>
#include <memory>
#include <unordered_map>
#include <shared_mutex>
#include <functional>
#include <yaml-cpp/yaml.h>
#include "VarConverter.hpp"

namespace ws {
namespace cfg {

class VarBase {
public:
  VarBase(const std::string_view name, const std::string_view description) noexcept;
  virtual ~VarBase() noexcept = default;

  std::string_view Name() const noexcept;
  std::string_view Description() const noexcept;
  virtual std::string ToString() const noexcept = 0;
  virtual void FromString(std::string_view str) = 0;
};

template <typename T, typename FromStr = VarConverter<std::string, T>, typename ToStr = VarConverter<T, std::string>>
class Var : public VarBase {
public:
  Var(const std::string_view name, const T& default_val, const std::string_view description = "") noexcept;
  std::string ToString() const noexcept override;
  void FromString(const std::string_view str) override;
  T GetValue() const noexcept;
  void SetValue(const T& val) noexcept;
  std::string_view TypeName() const noexcept;

  void RemoveListener(const std::uint64_t key) noexcept;
  std::uint64_t AddListener(OnChange listener) noexcept;
  void ClearListeners() noexcept;

private:
  T val_; 
  std::shared_mutex mtx_; 
  std::unordered_map<std::uint64_t, OnChange> listeners_; 
};

using VarPtr = std::shared_ptr<VarBase>;

class Config {
public:
  Config(const std::string_view name) noexcept;
  std::string_view Name() const noexcept;

  template <typename T>
  VarPtr Lookup(const std::string_view name, const T& default_val, const std::string_view description = "") ;

  template <typename T>
  VarPtr Lookup(const std::string_view name) const;

  VarBase::Ptr LookupBase(const std::string_view name) const noexcept;

  void LoadYaml(const YAML::Node& root);
  void Visit(const std::function<void(VarBase::Ptr)> visitor) const noexcept;

private:
  std::string name_; 
  std::unordered_map<std::string, VarBase::Ptr> vars_; 
  std::shared_mutex mtx_; 
};

using ConfigPtr = std::shared_ptr<Config>;

static inline ConfigPtr RootConfig() noexcept {
    static ConfigPtr instance(std::make_shared<Config>( "root" ));
    return instance;
}

typedef void (*OnChange)(const std::string& varName, const std::string& oldValue, const std::string& newValue);

} // namespace cfg
} // namespace ws

#endif // WS_CFG_CONFIG_HPP
